// Builds the WebAssembly decimator (Rust, no dependencies) and embeds it as base64 in packages/plugins/src/decimate.wasm.generated.ts.
// The generated file is committed, so a checkout builds and tests without a Rust toolchain. Run `npm run build:wasm` after changing the Rust source.
/* global process */
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const crate = path.join(root, 'packages/plugins/wasm/decimate')
execFileSync('cargo', ['build', '--release', '--target', 'wasm32-unknown-unknown'], { cwd: crate, stdio: 'inherit' })
const wasm = readFileSync(path.join(crate, 'target/wasm32-unknown-unknown/release/am_decimate.wasm'))
const b64 = wasm.toString('base64')
writeFileSync(path.join(root, 'packages/plugins/src/decimate.wasm.generated.ts'), `// Generated by scripts/build-wasm.mjs from wasm/decimate (Rust). Do not edit.\nexport const DECIMATE_WASM_BASE64 = '${b64}'\n`)
process.stdout.write(`decimate.wasm ${wasm.length} bytes\n`)
